  function bindEvents() {
    if (els.agentSearch) els.agentSearch.addEventListener('input', renderAgentList);
    bindAgentListClicks(els.agentList);
    bindAgentListClicks(els.agentListPersonal);
    bindAgentListClicks(els.agentListOrg);
    bindAgentListClicks(els.agentListEnterprise);

    els.btnNewChat.addEventListener('click', function () {
      clearChat();
      renderWelcome();
    });
    if (els.btnCollapseSidebar) {
      els.btnCollapseSidebar.addEventListener('click', function (event) {
        event.stopPropagation();
        toggleSidebar();
      });
    }
    if (els.btnToggleAgents) {
      els.btnToggleAgents.addEventListener('click', function (event) {
        event.stopPropagation();
        toggleAgentMenu();
      });
    }
    if (els.btnTogglePersonal) {
      els.btnTogglePersonal.addEventListener('click', function (e) {
        e.stopPropagation();
        toggleGroup(els.groupPersonal, els.btnTogglePersonal);
      });
    }
    if (els.btnToggleOrg) {
      els.btnToggleOrg.addEventListener('click', function (e) {
        e.stopPropagation();
        toggleGroup(els.groupOrg, els.btnToggleOrg);
      });
    }
    if (els.btnToggleEnterprise) {
      els.btnToggleEnterprise.addEventListener('click', function (e) {
        e.stopPropagation();
        toggleGroup(els.groupEnterprise, els.btnToggleEnterprise);
      });
    }
    els.btnModel.addEventListener('click', function (event) {
      event.stopPropagation();
      els.capabilityPanel.classList.add('hidden');
      var opening = els.modelMenu.classList.contains('hidden');
      toggle(els.modelMenu);
      renderModelMenu();
      if (opening) positionModelMenu();
    });
    els.modelMenu.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-model]');
      if (!btn) return;
      state.model = btn.dataset.model;
      saveState();
      renderModelMenu();
      renderCapabilityPanel();
      els.modelMenu.classList.add('hidden');
      els.btnModel.setAttribute('aria-expanded', 'false');
    });
    els.btnCapability.addEventListener('click', function (event) {
      event.stopPropagation();
      els.modelMenu.classList.add('hidden');
      els.btnModel.setAttribute('aria-expanded', 'false');
      renderCapabilityPanel();
      positionCapabilityPanel();
      toggle(els.capabilityPanel);
    });
    els.btnCloseCapability.addEventListener('click', function () {
      els.capabilityPanel.classList.add('hidden');
    });
    els.promptSuggestions.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-prompt]');
      if (!btn) return;
      els.chatInput.value = btn.dataset.prompt;
      els.chatInput.focus();
    });
    els.chatSend.addEventListener('click', sendChat);
    els.chatInput.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault();
        sendChat();
      }
    });
    els.chatMsgs.addEventListener('click', function (event) {
      if (event.target.closest('[data-toggle-thinking]')) {
        var answer = event.target.closest('.aioq-answer');
        var detail = answer && answer.querySelector('.aioq-thinking-detail');
        if (detail) detail.classList.toggle('hidden');
      }
      if (event.target.closest('[data-view-source]') && typeof opts.onViewSource === 'function') {
        opts.onViewSource();
      } else if (event.target.closest('[data-view-source]')) {
        els.sourcePanel.classList.remove('hidden');
      }
      if (event.target.closest('[data-download-file]')) {
        if (typeof opts.onFileDownload === 'function') opts.onFileDownload(event.target.closest('[data-download-file]'));
        else flashButton(event.target.closest('[data-download-file]'));
      }
      if (event.target.closest('[data-copy-answer]')) flashButton(event.target.closest('[data-copy-answer]'));
      if (event.target.closest('[data-retry-answer]')) flashButton(event.target.closest('[data-retry-answer]'));
      if (event.target.closest('[data-like-answer]')) {
        var likeBtn = event.target.closest('[data-like-answer]');
        likeBtn.classList.toggle('is-active');
      }
      if (event.target.closest('[data-open-feedback]')) openFeedback();
      if (event.target.closest('[data-request-expert]') && typeof opts.onRequestExpert === 'function') {
        opts.onRequestExpert();
      }
      if (event.target.closest('[data-cite-mode]')) {
        var citeBtn = event.target.closest('[data-cite-mode]');
        var answer = citeBtn.closest('.aioq-answer');
        if (answer) {
          answer.querySelectorAll('[data-cite-mode]').forEach(function (b) { b.classList.remove('active'); });
          citeBtn.classList.add('active');
        }
        if (citeBtn.dataset.citeMode === 'excerpt' && typeof opts.onCiteExcerpt === 'function') {
          opts.onCiteExcerpt();
        }
      }
    });
    if (els.btnCloseSource) {
      els.btnCloseSource.addEventListener('click', function () {
        els.sourcePanel.classList.add('hidden');
      });
    }
    if (els.btnRetrySource) {
      els.btnRetrySource.addEventListener('click', function () {
        if (typeof opts.onRetrySource === 'function') opts.onRetrySource();
      });
    }
    if (els.btnFeedbackEntry) els.btnFeedbackEntry.addEventListener('click', openFeedback);
    if (els.btnCloseFeedback) els.btnCloseFeedback.addEventListener('click', closeFeedback);
    if (els.btnCancelFeedback) els.btnCancelFeedback.addEventListener('click', closeFeedback);
    if (els.btnSubmitFeedback) {
      els.btnSubmitFeedback.addEventListener('click', function () {
        if (typeof opts.onSubmitFeedback === 'function') {
          opts.onSubmitFeedback();
        } else {
          closeFeedback();
        }
      });
    }
    if (els.btnVoice) {
      els.btnVoice.addEventListener('click', function () {
        els.btnVoice.classList.add('is-recording');
        setTimeout(function () { els.btnVoice.classList.remove('is-recording'); }, 1200);
      });
    }
    window.addEventListener('resize', function () {
      if (!els.capabilityPanel.classList.contains('hidden')) positionCapabilityPanel();
      if (!els.modelMenu.classList.contains('hidden')) positionModelMenu();
    });
    document.addEventListener('click', closeFloatingPanels);
    els.modelMenu.addEventListener('click', function (event) { event.stopPropagation(); });
    els.capabilityPanel.addEventListener('click', function (event) { event.stopPropagation(); });
  }

  function applyUrlAgent() {
    try {
      var params = new URLSearchParams(global.location.search);
      var id = params.get('id');
      if (id && agentById(id)) {
        state.agentId = id;
        saveState();
      }
    } catch (e) {}
  }

  function init(options) {
    opts = options || {};
    if (opts.groupedAgents) {
      groupedAgents = opts.groupedAgents;
      runtimeAgents = allAgents();
    } else if (opts.agents) {
      runtimeAgents = opts.agents.slice();
      groupedAgents = null;
    } else {
      runtimeAgents = DEFAULT_AGENTS.slice();
      groupedAgents = null;
    }
    opts.mode = opts.mode || 'lite';

    state = loadState();
    applyUrlAgent();
    if (!agentById(state.agentId)) {
      state.agentId = allAgents()[0] ? allAgents()[0].id : 'agt_ocean';
    }
    saveState();

    els = {
      root: document.getElementById('userChatRoot'),
      agentMenuBlock: document.getElementById('agentMenuBlock'),
      btnToggleAgents: document.getElementById('btnToggleAgents'),
      agentList: document.getElementById('agentList'),
      agentListPersonal: document.getElementById('agentListPersonal'),
      agentListOrg: document.getElementById('agentListOrg'),
      agentListEnterprise: document.getElementById('agentListEnterprise'),
      groupPersonal: document.getElementById('groupPersonal'),
      groupOrg: document.getElementById('groupOrg'),
      groupEnterprise: document.getElementById('groupEnterprise'),
      btnTogglePersonal: document.getElementById('btnTogglePersonal'),
      btnToggleOrg: document.getElementById('btnToggleOrg'),
      btnToggleEnterprise: document.getElementById('btnToggleEnterprise'),
      agentDetailDrawer: document.getElementById('agentDetailDrawer'),
      agentSearch: document.getElementById('agentSearch'),
      btnNewChat: document.getElementById('btnNewChat'),
      btnCollapseSidebar: document.getElementById('btnCollapseSidebar'),
      btnModel: document.getElementById('btnModel'),
      modelLabel: document.getElementById('modelLabel'),
      modelMenu: document.getElementById('modelMenu'),
      stageScroll: document.querySelector('.aioq-stage-scroll'),
      welcomePanel: document.getElementById('welcomePanel'),
      welcomeName: document.getElementById('welcomeName'),
      welcomeDesc: document.getElementById('welcomeDesc'),
      chatMsgs: document.getElementById('chatMsgs'),
      chatInput: document.getElementById('chatInput'),
      chatSend: document.getElementById('chatSend'),
      promptSuggestions: document.getElementById('promptSuggestions'),
      btnCapability: document.getElementById('btnCapability'),
      capabilityPanel: document.getElementById('capabilityPanel'),
      capabilityContent: document.getElementById('capabilityContent'),
      btnCloseCapability: document.getElementById('btnCloseCapability'),
      sourcePanel: document.getElementById('sourcePanel'),
      btnCloseSource: document.getElementById('btnCloseSource'),
      btnRetrySource: document.getElementById('btnRetrySource'),
      feedbackModal: document.getElementById('chatFeedbackModal'),
      btnFeedbackEntry: document.getElementById('btnFeedbackEntry'),
      btnCloseFeedback: document.getElementById('btnCloseFeedback'),
      btnCancelFeedback: document.getElementById('btnCancelFeedback'),
