.aioq-msg-center-panel {
  width: min(640px, 96vw);
  max-height: 90vh;
}

.aioq-msg-center-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  border-bottom: 1px solid #e8edf3;
}

.aioq-msg-center-head h3 {
  margin: 0;
  font-size: 18px;
