/**
 * Web 用户端专项契约检查
 */
const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');
const vm = require('vm');

const root = path.join(__dirname, '..');
const webIndex = path.join(root, 'web端', 'index.html');
let fail = 0;

function pass(msg) {
  console.log('PASS:', msg);
}

function failCheck(msg) {
  console.error('FAIL:', msg);
  fail++;
}

function assert(cond, msg) {
  if (cond) pass(msg);
  else failCheck(msg);
}

console.log('=== web-portal-check ===\n');

const expectedWebPages = [
  'web端/index.html',
  'web端/专家工作台/workbench.html',
  'web端/专家工作台/task-detail.html',
  'web端/专家工作台/task-view.html',
  'web端/专家工作台/context.html'
];

expectedWebPages.forEach(function (rel) {
  assert(fs.existsSync(path.join(root, rel)), '页面存在 → ' + rel);
});

if (!fs.existsSync(webIndex)) {
  console.error('\nWEB-PORTAL-CHECK FAILED (missing index)');
  process.exit(1);
}

const html = fs.readFileSync(webIndex, 'utf8');
assert(html.includes('id="agentListPersonal"'), '三组智能体 → 个人列表');
assert(html.includes('id="agentListOrg"'), '三组智能体 → 组织列表');
assert(html.includes('id="agentListEnterprise"'), '三组智能体 → 企业列表');
assert(html.includes('id="agentGroups"'), '三组容器 → agentGroups');
assert(html.includes('id="groupEnterprise"') && !html.match(/id="groupEnterprise"[^>]*is-group-collapsed/), '企业组默认展开');
assert(!html.includes('is-agents-collapsed'), '智能体中心默认展开');
assert(html.indexOf('id="agentSearch"') < html.indexOf('id="agentMenuBlock"'), '搜索框在智能体中心之前');
assert(html.includes('id="btnMessageCenter"'), '消息中心入口');
assert(!html.includes('>意见箱<'), '侧栏无意见箱文案');
assert(html.includes('user-message-center.js'), '消息中心脚本');
assert(html.includes('user-portal-bridge.js'), '桥接层脚本');
assert(html.includes('专家工作台/workbench.html'), '专家工作台入口');

const workbenchHtml = fs.readFileSync(path.join(root, 'web端', '专家工作台', 'workbench.html'), 'utf8');
assert(workbenchHtml.includes('id="userPortalSidebar"'), '专家工作台 → 用户侧栏容器');
assert(workbenchHtml.includes('user-portal-shell.js'), '专家工作台 → user-portal-shell');
assert(!workbenchHtml.includes('class="sidebar"'), '专家工作台 → 无运营 sidebar');

const assets = [
  'assets/user-portal-context.js',
  'assets/user-agent-resolver.js',
  'assets/user-portal-bridge.js',
  'assets/user-message-center.js',
  'assets/user-portal-shell.js'
];
assets.forEach(function (rel) {
  assert(fs.existsSync(path.join(root, rel)), '共享脚本存在 → ' + rel);
});

['assets/user-portal-context.js', 'assets/user-agent-resolver.js', 'assets/user-portal-bridge.js', 'assets/user-message-center.js', 'assets/user-portal-shell.js'].forEach(function (rel) {
  try {
    require('child_process').execSync('node --check "' + path.join(root, rel) + '"', { stdio: 'pipe' });
    pass('语法检查 → ' + rel);
  } catch (e) {
    failCheck('语法检查失败 → ' + rel);
  }
});

try {
  const dom = new JSDOM(html, {
    runScripts: 'outside-only',
    url: 'file://' + webIndex.replace(/\\/g, '/'),
    resources: 'usable',
    pretendToBeVisual: true
  });
  const doc = dom.window.document;
  assert(doc.getElementById('groupPersonal'), 'DOM → groupPersonal');
  assert(doc.getElementById('groupOrg'), 'DOM → groupOrg');
  assert(doc.getElementById('groupEnterprise'), 'DOM → groupEnterprise');
  assert(doc.getElementById('btnMessageCenter'), 'DOM → btnMessageCenter');
} catch (e) {
  failCheck('jsdom 解析 web端/index.html 失败: ' + e.message);
}

try {
  const resolverCode = fs.readFileSync(path.join(root, 'assets', 'user-agent-resolver.js'), 'utf8');
  const chatCode = fs.readFileSync(path.join(root, 'assets', 'user-chat-portal.js'), 'utf8');
  const sandbox = {
    window: {},
    sessionStorage: {
      _d: {},
      getItem(k) { return this._d[k] || null; },
      setItem(k, v) { this._d[k] = v; }
    },
    console: console
  };
  sandbox.window = sandbox;
  vm.createContext(sandbox);
  vm.runInContext(chatCode, sandbox);
  vm.runInContext(resolverCode, sandbox);
  const grouped = sandbox.UserAgentResolver.resolve({ userId: 'user_zhang', userName: '张三', departmentIds: ['team_platform'] });
  assert(grouped.enterprise.length >= 10, '企业组智能体 ≥ 10（DEFAULT_AGENTS 兜底）');
} catch (e) {
  failCheck('UserAgentResolver 运行时检查失败: ' + e.message);
}

const resolverJs = fs.readFileSync(path.join(root, 'assets', 'user-agent-resolver.js'), 'utf8');
assert(resolverJs.includes('UserAgentResolver'), 'UserAgentResolver 导出');
assert(resolverJs.includes('getDefaultAgents'), '始终合并 DEFAULT_AGENTS');
assert(resolverJs.includes('proto_ops_v11_agents'), 'v11 状态读取');

const bridgeJs = fs.readFileSync(path.join(root, 'assets', 'user-portal-bridge.js'), 'utf8');
assert(bridgeJs.includes('proto_user_chat_history'), '历史记录 key');
assert(bridgeJs.includes('createFromChat'), '反馈闭环接线');
assert(bridgeJs.includes('UserMessageCenter'), '消息中心接线');

if (fail) {
  console.error('\nWEB-PORTAL-CHECK FAILED (' + fail + ' issue(s))');
  process.exit(1);
}
console.log('\nWEB-PORTAL-CHECK PASSED');
process.exit(0);

