input.contents:
# Figma MCP 双通道健康检查（配置 + Desktop 可达性 + 项目映射）
param(
  [switch]$StrictDesktop
)

$ErrorActionPreference = 'Continue'
$root = Split-Path -Parent $PSScriptRoot
$configPath = Join-Path $root 'design\figma.config.json'
$mcpPath = Join-Path $env:USERPROFILE '.cursor\mcp.json'
$fail = 0
$warn = 0

function Pass($msg) { Write-Host "PASS: $msg" -ForegroundColor Green }
function Warn($msg) { Write-Host "WARN: $msg" -ForegroundColor Yellow; $script:warn++ }
function Fail($msg) { Write-Host "FAIL: $msg" -ForegroundColor Red; $script:fail++ }

Write-Host "=== verify-figma-mcp ===" -ForegroundColor Cyan
Write-Host ""

if (Test-Path $configPath) {
  Pass "design/figma.config.json 存在"
  $cfg = Get-Content $configPath -Raw | ConvertFrom-Json
  if ($cfg.files.prototype.fileKey) {
    Pass ("fileKey = " + $cfg.files.prototype.fileKey)
  } else {
    Fail "figma.config.json 缺少 fileKey"
  }
  $screenCount = ($cfg.files.prototype.screens.PSObject.Properties | Measure-Object).Count
  if ($screenCount -ge 1) {
    Pass ("已映射 screens = $screenCount")
  } else {
    Fail "figma.config.json 无 screens 映射"
  }
} else {
  Fail "缺少 design/figma.config.json"
}

if (Test-Path $mcpPath) {
  $mcp = Get-Content $mcpPath -Raw | ConvertFrom-Json
  if ($mcp.mcpServers.figma) { Pass "~/.cursor/mcp.json 含 figma (Remote OAuth)" }
  else { Fail "~/.cursor/mcp.json 缺少 figma → https://mcp.figma.com/mcp" }
  if ($mcp.mcpServers.'figma-desktop') { Pass "~/.cursor/mcp.json 含 figma-desktop (本地 3845)" }
  else { Fail "~/.cursor/mcp.json 缺少 figma-desktop → http://127.0.0.1:3845/mcp" }
} else {
  Fail "~/.cursor/mcp.json 不存在"
}

$desktopUrl = 'http://127.0.0.1:3845/mcp'
try {
  $tcp = New-Object System.Net.Sockets.TcpClient
  $iar = $tcp.BeginConnect('127.0.0.1', 3845, $null, $null)
  $ok = $iar.AsyncWaitHandle.WaitOne(2000, $false)
  if ($ok -and $tcp.Connected) {
    $tcp.Close()
    Pass "Figma Desktop MCP 端口 3845 已监听"
  } else {
    $tcp.Close()
    if ($StrictDesktop) { Fail "Figma Desktop MCP 未启动（请在桌面版 Dev Mode 开启 MCP Server）" }
    else { Warn "Figma Desktop MCP 未启动 — 打开 Figma Desktop → Dev Mode → Enable MCP Server" }
  }
} catch {
  if ($StrictDesktop) { Fail "无法连接 127.0.0.1:3845 — $($_.Exception.Message)" }
  else { Warn "Figma Desktop MCP 未就绪 — 打开 Figma Desktop → Dev Mode → Enable MCP Server" }
}

$resolveJs = Join-Path $root 'scripts\resolve-figma-screen.js'
if (Test-Path $resolveJs) {
  $sample = node $resolveJs --html "prototype/web端/index.html" 2>$null
  if ($LASTEXITCODE -eq 0 -and $sample) {
    Pass "resolve-figma-screen.js 可解析 userChat"
  } else {
    Warn "resolve-figma-screen.js 运行异常"
  }
} else {
  Warn "缺少 scripts/resolve-figma-screen.js"
}

Write-Host ""
if ($fail -gt 0) {
  Write-Host "FIGMA MCP CHECK FAILED ($fail fail, $warn warn)" -ForegroundColor Red
  exit 1
}
if ($warn -gt 0) {
  Write-Host "FIGMA MCP CHECK PASSED WITH WARNINGS ($warn)" -ForegroundColor Yellow
  exit 0
